#[derive(Clone, Copy, Debug, PartialEq)]
struct Complex {
    re: i32,
    im: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    let machine_epsilon: i32 = 2;
    let threshold = tol * machine_epsilon;
    
    // Check if all imaginary parts are close to zero
    let all_close = arr.iter().all(|c| c.im.abs() <= threshold);
    
    if all_close {
        // Return array with imaginary parts set to zero
        arr.iter()
            .map(|c| Complex { re: c.re, im: 0 })
            .collect()
    } else {
        // Return the input array unchanged
        arr
    }
}